INSERT [dbo].[Laptop] ([malaptop], [tenlaptop], [giaban], [mota], [hinh], [mahang], [manhucau], [cpu], [gpu], [ram], [hardware], [manhinh], [ngaycapnhat], [soluongton], [pin], [trangthai]) VALUES (26, N'Laptop Acer Swift 5 Evo SF514-55TA-59N4', CAST(27990000 AS Decimal(18, 0)), N'<h3><a href="https://phongvu.vn/laptop-macbook-scat.01-N001">M&aacute;y t&iacute;nh x&aacute;ch tay</a>&nbsp;Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) c&oacute; được vẻ ngo&agrave;i mạnh mẽ, kết hợp được b&agrave;n ph&iacute;m t&iacute;ch hợp đ&egrave;n LED độc đ&aacute;o. Đồng thời, m&aacute;y t&iacute;nh c&ograve;n sở hữu được pin 40Wh tối ưu, cho ph&eacute;p bạn chơi game li&ecirc;n tục trong nhiều giờ liền. Đ&acirc;y ch&iacute;nh x&aacute;c l&agrave; một sản phẩm d&agrave;nh ri&ecirc;ng cho d&acirc;n văn ph&ograve;ng.</h3>

<h4><strong>Thiết kế hiện đại v&agrave; mạnh mẽ, sở hữu m&agrave;n h&igrave;nh 14 inch chất lượng si&ecirc;u cao</strong></h4>

<p>M&aacute;y t&iacute;nh x&aacute;ch tay Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) c&oacute; được thiết kế v&ocirc; c&ugrave;ng mạnh mẽ v&agrave; kh&ocirc;ng k&eacute;m phần hiện đại, vốn được d&agrave;nh ri&ecirc;ng cho d&acirc;n văn ph&ograve;ng n&ecirc;n k&iacute;ch thước cũng v&ocirc; c&ugrave;ng nhỏ gọn, c&oacute; khối lượng 1 kg v&agrave; chỉ 31.89 x 20.698 x 1.495 cm, dễ d&agrave;ng di chuyển đến mọi nơi để l&agrave;m việc ở cường độ cao.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | Thiết kế hiện đại" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_d1da990e-7e4c-4545-ba72-7e5cc0cb9b7a.jpg" /></p>

<p>Kh&ocirc;ng những thế, m&aacute;y t&iacute;nh Acer c&ograve;n sở hữu được m&agrave;n h&igrave;nh 14 inch chất lượng cao, với độ ph&acirc;n giải (1920 x 1080 pixels) k&egrave;m theo tấm nền IPS chống ch&oacute;i l&oacute;a tối ưu, đem lại h&igrave;nh ảnh sống động v&agrave; sắc n&eacute;t chưa từng thấy, đảm bảo mọi giờ khắc giải tr&iacute; của bạn sẽ kh&ocirc;ng bao giờ bị nh&ograve;e hoặc c&oacute; hiện tượng vỡ h&igrave;nh.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | Màn hình 14 inch" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_f10ddfb0-353e-4655-ba89-110dc1b69935.jpg" /></p>

<h4><strong>Sở hữu bộ vi xử l&yacute; Intel Core i5 1135G7 thế hệ mới, được trang bị th&ecirc;m thanh RAM 16GB cải thiện tốc độ đa nhiệm h&oacute;a</strong></h4>

<p>B&ecirc;n cạnh đ&oacute;, m&aacute;y t&iacute;nh x&aacute;ch tay Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) sở hữu được bộ vi xử l&yacute; Intel Core i5 1135G7 thế hệ mới hiện đại, c&oacute; tốc độ xung nhịp tối đa tận 4.2GHz, kết hợp c&ugrave;ng 4 nh&acirc;n 8 luồng xử l&yacute; đỉnh cao, đem đến khả năng khởi chạy nhanh ch&oacute;ng c&aacute;c thao t&aacute;c tr&ecirc;n m&aacute;y nhanh ch&oacute;ng v&agrave; mượt m&agrave; hơn.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | Hiệu năng mạnh mẽ" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_8a8135fa-6f81-44a0-9438-409f2091768e.jpg" /></p>

<p>Đặc biệt hơn, m&aacute;y t&iacute;nh x&aacute;ch tay Acer c&ograve;n được trang bị th&ecirc;m thanh RAM 16GB chuẩn LPDDR4X, gi&uacute;p cải thiện được c&aacute;c t&aacute;c vụ đa nhiệm cơ bản, hỗ trợ người d&ugrave;ng c&oacute; thể sử dụng được c&ugrave;ng l&uacute;c rất nhiều loại ứng dụng v&agrave; phần mềm. Đồng thời, với RAM 16GB, bạn c&ograve;n c&oacute; thể duyệt web nhiều tab m&agrave; kh&ocirc;ng sợ bị lag m&aacute;y.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | Ram 16GB" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_c3f893d5-4a44-4942-897b-3d4b7fbea13c.jpg" /></p>

<h4><strong>Được trang bị card đồ họa Intel Iris Xe Graphics hiện đại, kết hợp c&ugrave;ng ổ cứng 1TB SSD rộng lớn</strong></h4>

<p>Kh&ocirc;ng dừng lại ở đ&oacute;, m&aacute;y t&iacute;nh x&aacute;ch tay Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) c&ograve;n được trang bị th&ecirc;m card đồ họa Intel Iris Xe Graphics hiện đại, cho ph&eacute;p bạn sử dụng trơn tru c&aacute;c ứng dụng văn ph&ograve;ng nặng, thậm ch&iacute; l&agrave; c&aacute;c tựa game nhập vai hot nhất hiện nay với đồ họa đỉnh cao.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | Chip đồ họa mới" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_8951e21a-6953-4613-9daf-3381c6ce521a.jpg" /></p>

<p>Ngo&agrave;i ra, m&aacute;y t&iacute;nh Acer c&ograve;n c&oacute; được ổ cứng 1TB SSD chuẩn M.2 NVMe đem lại cho bạn một kh&ocirc;ng gian lưu trữ thoải m&aacute;i c&aacute;c dữ liệu, bao gồm: H&igrave;nh ảnh, video, t&agrave;i liệu, ebook, game, &acirc;m nhạc, phim ảnh,.... Đồng thời, ổ cứng rộng lớn c&ograve;n gi&uacute;p việc truyền ph&aacute;t dữ liệu của m&aacute;y được cải thiện nhanh ch&oacute;ng v&agrave; tiện lợi hơn.</p>

<p><img alt="Acer Swift 5 SF514-55TA-59N4 | SSD 1TB" src="https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/8/20/20210820_2f8a229f-ab4d-4562-8401-9f755302a4d7.jpg" /></p>

<p>Kh&ocirc;ng những thế, m&aacute;y t&iacute;nh Acer Swift c&ograve;n sở hữu pin 40Wh bền l&acirc;u, c&oacute; thể gi&uacute;p bạn chơi game cường độ cao li&ecirc;n tục trong nhiều giờ.</p>

<h4><strong>Mua m&aacute;y t&iacute;nh x&aacute;ch tay Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) ch&iacute;nh h&atilde;ng, đến Phong Vũ để được nhận c&aacute;c ưu đ&atilde;i về gi&aacute; th&agrave;nh cực sốc</strong></h4>

<p>M&aacute;y t&iacute;nh x&aacute;ch tay Acer Swift 5 SF514-55TA-59N4 (NX.A6SSV.001) c&oacute; vẻ ngo&agrave;i hiện đại v&agrave; mạnh mẽ, kết hợp với bộ vi xử l&yacute; Intel Core i5 thế hệ mới hiện đại, đ&acirc;y ch&iacute;nh l&agrave; sản phẩm d&agrave;nh ri&ecirc;ng cho d&acirc;n văn ph&ograve;ng. Mua sắm tại&nbsp;<a href="https://phongvu.vn/phongvu.vn">Phong Vũ</a>&nbsp;để được nhận cơ hội hưởng c&aacute;c dịch vụ ưu đ&atilde;i về gi&aacute; th&agrave;nh sốc tận &oacute;c đấy nh&eacute;!</p>
', N'Laptop-Acer-Swift 5-Evo-SF514-55TA-59N4.jpg', 4, 3, N'i5-1135G7', N'Intel Iris Xe Graphics ', N'16GB', N'SSD 256GB', N'15.6 inch', CAST(N'2022-05-26T00:00:00.000' AS DateTime), 24, N'3 Cell 43WHr', 1)
INSERT [dbo].[Laptop] ([malaptop], [tenlaptop], [giaban], [mota], [hinh], [mahang], [manhucau], [cpu], [gpu], [ram], [hardware], [manhinh], [ngaycapnhat], [soluongton], [pin], [trangthai]) VALUES (27, N'Laptop Acer Swift 3 SF314-511-56G1', CAST(20990000 AS Decimal(18, 0)), N'<h3>Acer Swift 3 SF314 511 56G1 (NX.ABLSV.002) xứng đ&aacute;ng trở th&agrave;nh một trong những lựa chọn h&agrave;ng đầu cho người d&ugrave;ng trong ph&acirc;n kh&uacute;c&nbsp;<a href="https://www.thegioididong.com/laptop?g=hoc-tap-van-phong" target="_blank" title="Xem thêm các mẫu Laptop học tập - văn phòng hiện đang kinh doanh tại thegioididong.com">laptop học tập - văn ph&ograve;ng</a>&nbsp;với thiết kế gọn nhẹ, sang trọng c&ugrave;ng hiệu năng vượt trội đ&ecirc;n từ<a href="https://www.thegioididong.com/laptop-cpu-intel-gen-11" target="_blank" title="Xem thêm laptop trang bị CPU thế hệ 11 đang bán tại thegioididong.com">&nbsp;CPU Intel thế hệ 11</a>&nbsp;t&acirc;n tiến.</h3>

<h3>Thiết kế mỏng nhẹ, ph&ugrave; hợp với mọi đối tượng người d&ugrave;ng</h3>

<p>Swift 3 SF314 thu h&uacute;t mọi &aacute;nh nh&igrave;n với chiếc &aacute;o&nbsp;<strong>m&agrave;u bạc</strong>&nbsp;v&agrave; lớp&nbsp;<strong>vỏ bằng kim loại</strong>&nbsp;nguy&ecirc;n khối gi&uacute;p m&aacute;y trở n&ecirc;n bền bỉ v&agrave; cứng c&aacute;p nhưng vẫn kh&ocirc;ng k&eacute;m phần tinh tế sang trọng. Với độ d&agrave;y chỉ vỏn vẹn&nbsp;<strong>15.9 mm</strong>&nbsp;v&agrave; trọng lượng nhẹ&nbsp;<strong>1.19 kg</strong>,&nbsp;<a href="https://www.thegioididong.com/laptop-acer-swift" target="_blank" title="Xem thêm các mẫu Laptop Acer Swift hiện đang kinh doanh tại thegioididong.com">Acer Swift</a>&nbsp;cho ph&eacute;p người d&ugrave;ng di chuyển m&aacute;y linh hoạt ở khắp mọi nơi.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-2.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Thiết kế" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-2.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Thiết kế" /></a></p>

<p>K&iacute;ch thước b&agrave;n ph&iacute;m đầy đủ với h&agrave;nh tr&igrave;nh ph&iacute;m s&acirc;u v&agrave;&nbsp;<strong>đ&egrave;n nền</strong>&nbsp;được t&iacute;ch hợp tr&ecirc;n&nbsp;<a href="https://www.thegioididong.com/laptop-acer" target="_blank" title="Xem thêm các mẫu Laptop Acer hiện đang kinh doanh tại thegioididong.com">laptop Acer</a>&nbsp;mang đến cho người d&ugrave;ng trải nghiệm đ&aacute;nh m&aacute;y soạn thảo văn bản thoải m&aacute;i với độ nảy tốt d&ugrave; trong m&ocirc;i trường thiếu s&aacute;ng.</p>

<p>T&iacute;nh năng&nbsp;<strong>bảo mật v&acirc;n tay</strong>&nbsp;được trang bị tr&ecirc;n Acer Swift gi&uacute;p bạn khởi động m&aacute;y nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng chỉ với một c&aacute;i chạm nhẹ đơn giản.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-6.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Vân tay" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-6.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Vân tay" /></a></p>

<p>Dọc th&acirc;n m&aacute;y l&agrave;<strong>&nbsp;</strong>2 cổng USB 3.2, HDMI<strong>,</strong>&nbsp;Thunderbolt 4 USB-C&nbsp;mang lại khả năng vừa truyền dữ liệu vừa sạc pin nhanh ch&oacute;ng th&ocirc;ng qua 1 cổng duy nhất, cho ph&eacute;p bạn xử l&yacute; c&aacute;c c&ocirc;ng việc một c&aacute;ch dễ d&agrave;ng v&agrave; ch&iacute;nh x&aacute;c nhưng vẫn tối ưu h&oacute;a được nguồn pin.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-9.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Cổng kết nối" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-9.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Cổng kết nối" /></a></p>

<p>Chuẩn&nbsp;<strong>Bluetooth 5.1</strong>&nbsp;v&agrave; Wi-Fi 6 (802.11ax) cho độ trễ thấp v&agrave; cải tiến tốc độ tốt hơn với đường truyền l&ecirc;n đến&nbsp;<strong>10 Gbps</strong>, gi&uacute;p cho thiết bị được kết nối kh&ocirc;ng d&acirc;y nhanh ch&oacute;ng v&agrave; ch&iacute;nh x&aacute;c đồng thời tiết kiệm điện hơn c&aacute;c thế hệ tiền nhiệm.</p>

<h3>Hiệu năng mạnh mẽ cho mọi t&aacute;c vụ văn ph&ograve;ng</h3>

<p>Swift 3 SF314 511 mang trong m&igrave;nh con chip<a href="https://www.thegioididong.com/laptop?g=core-i5" target="_blank" title="Xem thêm các mẫu Laptop có CPU Intel Core i5 hiện đang kinh doanh tại thegioididong.com">&nbsp;Intel Core i5&nbsp;</a><strong>Tiger Lake 1135G7&nbsp;</strong>mạnh mẽ gi&uacute;p bạn thực hiện tốt c&aacute;c t&aacute;c vụ văn ph&ograve;ng từ cơ bản đến n&acirc;ng cao một c&aacute;ch nhanh gọn v&agrave; ch&iacute;nh x&aacute;c nhờ&nbsp;<strong>CPU 4 nh&acirc;n 8 luồng</strong>, đồng thời tiết kiệm điện năng hơn với c&ocirc;ng nghệ&nbsp;<strong>Turbo boost&nbsp;</strong>&eacute;p xung tối đa l&ecirc;n đến&nbsp;<strong>4.2 GHz</strong>.</p>

<p><strong>Card đồ họa t&iacute;ch hợp</strong>&nbsp;<a href="https://www.thegioididong.com/hoi-dap/tim-hieu-ve-card-do-hoa-tich-hop-intel-iris-xe-graphics-1305192" target="_blank" title="Tìm hiểu về card đồ họa Intel Iris Xe Graphics">Intel Iris Xe Graphics&nbsp;</a>cho chất lượng xuất ảnh l&ecirc;n đến&nbsp;<strong>8K</strong>&nbsp;với hiệu suất đồ họa mạnh mẽ, thao t&aacute;c mượt m&agrave; v&agrave; chuy&ecirc;n nghiệp hơn tr&ecirc;n c&aacute;c phần mềm Photoshop, AI,... thậm ch&iacute; l&agrave; chơi c&aacute;c tựa game c&oacute; mức c&agrave;i đặt trung b&igrave;nh như LOL, FIFA,&nbsp;Warframe,...</p>

<p><a href="https://www.thegioididong.com/laptop?g=16-gb" target="_blank" title="Xem thêm các mẫu Laptop có RAM 16 GB hiện đang kinh doanh tại thegioididong.com">RAM 16 GB&nbsp;</a>chuẩn&nbsp;<strong>LPDDR4X (On board)</strong>&nbsp;với tốc độ bus RAM l&ecirc;n đến&nbsp;<strong>4266 MHz&nbsp;</strong>v&agrave; tiến tr&igrave;nh&nbsp;<strong>10nm&nbsp;</strong>nhỏ gọn cho băng th&ocirc;ng cao hơn&nbsp;<strong>30%</strong>&nbsp;so với c&aacute;c thế hệ trước, gi&uacute;p người d&ugrave;ng n&acirc;ng cao hiệu suất l&agrave;m việc với độ đa nhiệm cao, thuận tiện khi vừa l&agrave;m việc văn ph&ograve;ng vừa lướt web tra cứu th&ocirc;ng tin m&agrave; vẫn tiết kiệm điện năng đ&aacute;ng kể.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-4.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Cấu hình" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-4.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Cấu hình" /></a></p>

<p>Ổ cứng&nbsp;<a href="https://www.thegioididong.com/laptop?g=ssd-512-gb" target="_blank" title="Xem thêm các mẫu Laptop có ổ cứng SSD 512 GB hiện đang kinh doanh tại thegioididong.com">SSD 512 GB&nbsp;</a><strong>NVMe PCIe</strong>&nbsp;mang đến tốc độ khởi động m&aacute;y v&agrave; ứng dụng nhanh ch&oacute;ng chỉ trong v&agrave;i gi&acirc;y, cho ph&eacute;p bạn lưu trữ những tệp tin hữu &iacute;ch hay những bộ phim y&ecirc;u th&iacute;ch khi c&oacute; thể th&aacute;o ra v&agrave; lắp thanh kh&aacute;c với dung lượng tối đa l&ecirc;n đến&nbsp;<strong>1TB</strong>.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-5.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - SSD" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-5.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - SSD" /></a></p>

<h3>Trải nghiệm h&igrave;nh ảnh, &acirc;m thanh tr&ecirc;n cả tuyệt vời</h3>

<p>Tận hưởng những khung h&igrave;nh sắc n&eacute;t, sống động với k&iacute;ch&nbsp;<a href="https://www.thegioididong.com/laptop-14-inch" target="_blank" title="Xem thêm các mẫu Laptop có kích thước MH 14 inch hiện đang kinh doanh tại thegioididong.com">m&agrave;n h&igrave;nh 14 inch&nbsp;</a>kết hợp độ ph&acirc;n giải&nbsp;<strong>Full HD (1920x1080)&nbsp;</strong>v&agrave;<strong>&nbsp;tấm nền IPS,</strong>&nbsp;gi&uacute;p bạn đắm ch&igrave;m v&agrave;o kh&ocirc;ng gian hiển thị rộng l&ecirc;n đến&nbsp;<strong>178 độ</strong>.</p>

<p>C&ocirc;ng nghệ m&agrave;n h&igrave;nh&nbsp;<strong>TFT</strong>&nbsp;v&agrave;<a href="https://www.thegioididong.com/hoi-dap/cong-nghe-man-hinh-acer-comfyview-co-gi-dac-biet-1192380" target="_blank" title="Tìm hiểu thêm về công nghệ màn hình Acer ComfyView">&nbsp;Acer ComfyView</a>&nbsp;cho chất lượng hiển thị chi tiết hơn với &aacute;nh s&aacute;ng đầy đủ, độ tương phản cao v&agrave; chuyển động mượt m&agrave;, mang lại cảm gi&aacute;c m&atilde;n nh&atilde;n cho người d&ugrave;ng tr&ecirc;n từng khung h&igrave;nh phim ảnh.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-7.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Hình ảnh" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-7.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Hình ảnh" /></a></p>

<p>C&ocirc;ng nghệ &acirc;m thanh&nbsp;<strong>Acer TrueHarmony</strong>&nbsp;kết hợp với&nbsp;<strong>DTS Audio</strong>&nbsp;mang lại cho&nbsp;<a href="https://www.thegioididong.com/laptop" target="_blank" title="Xem thêm các mẫu Laptop hiện đang kinh doanh tại thegioididong.com">laptop</a>&nbsp;chuẩn mực &acirc;m thanh chất lượng cao với &acirc;m bass to r&otilde; v&agrave; khả năng lọc, khử tiếng ồn tốt, mang đến cho bạn những gi&acirc;y ph&uacute;t thư gi&atilde;n bất tận.</p>

<p><a href="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-8.jpg" onclick="return false;"><img alt="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Âm thanh" src="https://cdn.tgdd.vn/Products/Images/44/246959/acer-swift-3-sf314-511-56g1-i5-nxablsv002-8.jpg" title="Acer Swift 3 SF314 511 56G1 i5 1135G7 (NX.ABLSV.002) - Âm thanh" /></a></p>

<p>X&eacute;t tổng thể,&nbsp;<a href="https://www.thegioididong.com/laptop/acer-swift-3-sf314-511-56g1-i5-nxablsv002" target="_blank" title="Laptop Acer Swift 3 SF314 511 56G1 (NX.ABLSV.002)">Laptop Acer Swift 3 SF314 511 56G1 (NX.ABLSV.002)</a>&nbsp;đủ tự tin để trở th&agrave;nh trợ thủ đắc lực nhất đ&aacute;p ứng c&aacute;c nhu cầu văn ph&ograve;ng của người d&ugrave;ng bởi thiết kế gọn nhẹ đi k&egrave;m những th&ocirc;ng số kỹ thuật ấn tượng.</p>
', N'Laptop-Acer-Swift-3-SF314-511-56G1.jpg', 4, 3, N'i5-1135G7', N' Intel Iris Xe Graphics  ', N'8GB', N'SSD 256GB', N'14 inch', CAST(N'2022-04-11T00:00:00.000' AS DateTime), 24, N'3 Cell 43WHr', 1)
