INSERT [dbo].[TinTuc] ([matin], [tieude], [hinhnen], [tomtat], [slug], [noidung], [luotxem], [ngaycapnhat], [xuatban], [machude]) VALUES (1, N'Hướng dẫn cài đặt Win 10', N'huong-dan-cai-win-10.png', NULL, N'huong-dan-cai-win-10', N'<h3><strong>Lợi &iacute;ch của việc c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<ul>
	<li>Dễ d&agrave;ng thực hiện, c&oacute; thể di chuyển c&agrave;i đặt cho nhiều thiết bị.</li>
	<li>Đ&acirc;y được xem l&agrave; một trong những c&aacute;ch c&agrave;i Win 10 đơn giản nhất hiện nay, thậm ch&iacute; người c&oacute; kiến thức hạn chế về laptop cũng c&oacute; thể l&agrave;m được.</li>
</ul>

<h3><strong>Y&ecirc;u cầu cấu h&igrave;nh tối thiểu để c&agrave;i Windows 10</strong></h3>

<ul>
	<li>Bộ vi xử l&yacute;: Tốc độ tối thiểu 1 GHz , c&oacute; hỗ trợ PAE, NX v&agrave; SSE2.</li>
	<li>Dung lượng RAM: Tối thiểu 1 GB (đối với phi&ecirc;n bản 32 bit) hoặc 2 GB (đối với phi&ecirc;n bản 64 bit).</li>
	<li>Bộ nhớ tối thiểu: 16 GB (với bản 32 bit) hoặc 20 GB (với bản 64 bit).</li>
	<li>Card đồ họa: Microsoft DirectX 9 với tr&igrave;nh điều khiển WDDM.</li>
</ul>

<h3><strong>Tổng quan quy tr&igrave;nh c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<p><img alt="USB Boot" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-2.JPG" style="height:452px; width:730px" title="USB Boot" /></p>

<p><strong>Bước 1:&nbsp;</strong>Tải file c&agrave;i đặt Windows 10 (file ISO).</p>

<p><strong>Bước 2:&nbsp;</strong>Sử dụng USB để tạo USB Boot cho file c&agrave;i đặt Windows 10 vừa tải về.</p>

<p><strong>Bước 3:&nbsp;</strong>Sử dụng USB Boot vừa tạo để c&agrave;i đặt Windows 10 tr&ecirc;n m&aacute;y t&iacute;nh, laptop.</p>

<h3><strong>Cần chuẩn bị g&igrave; trước khi c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<p>Cần tải về file c&agrave;i đặt Windows 10 (file ISO), cụ thể hơn bạn c&oacute; thể xem hướng dẫn sau:</p>

<ul>
	<li><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-cach-tai-windows-10-1218719" target="_blank" title="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft" type="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft">C&aacute;ch tải Windows 10, tải file ISO Windows 10 ch&iacute;nh thức từ Microsoft</a>.</li>
</ul>

<p><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-cach-tai-windows-10-1218719" target="_blank" title="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft" type="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft">​​​</a>​Chuẩn bị USB c&oacute; dung lượng lớn hơn 4 GB, sau đ&oacute; tạo USB Boot cho qu&aacute; tr&igrave;nh c&agrave;i Windows 10, chi tiết hơn bạn c&oacute; thể tham khảo hướng dẫn sau:</p>

<ul>
	<li><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-tao-usb-boot-de-cai-win-tren-ca-2-chuan-1218657" target="_blank" title="Hướng dẫn tạo USB Boot cài WIN 7, 10 trên cả 2 chuẩn UEFI và LEGACY" type="Hướng dẫn tạo USB Boot cài WIN 7, 10 trên cả 2 chuẩn UEFI và LEGACY">Hướng dẫn tạo USB Boot c&agrave;i WIN 7, 10 tr&ecirc;n cả 2 chuẩn UEFI v&agrave; LEGACY.</a></li>
</ul>

<h3><strong>Hướng dẫn c&aacute;ch c&agrave;i đặt Windows 10 đơn giản nhất bằng USB Boot</strong></h3>

<p>Thời gian c&agrave;i đặt Windows 10 nhanh hay chậm t&ugrave;y thuộc v&agrave;o tốc độ đọc ghi USB v&agrave; cấu h&igrave;nh m&aacute;y t&iacute;nh người d&ugrave;ng. Th&ocirc;ng thường qu&aacute; tr&igrave;nh n&agrave;y mất tầm&nbsp;<strong>20-60 ph&uacute;t</strong>.</p>

<p><strong>Bước 1:</strong>&nbsp;Kết nối USB Boot vừa chuẩn bị ở tr&ecirc;n v&agrave;o m&aacute;y t&iacute;nh, laptop cần c&agrave;i Win 10.</p>

<p><strong>Bước 2:&nbsp;</strong>Nhấn n&uacute;t&nbsp;<strong>nguồn&nbsp;</strong>để khởi động m&aacute;y, khi&nbsp;<a href="https://www.dienmayxanh.com/man-hinh-may-tinh" target="_blank" title="màn hình máy tính">m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh</a>&nbsp;vừa bật bạn h&atilde;y&nbsp;<strong>nhấn li&ecirc;n tục ph&iacute;m tắt</strong>&nbsp;để truy cập v&agrave;o&nbsp;<strong>menu BOOT</strong>. Mỗi d&ograve;ng laptop kh&aacute;c nhau sẽ c&oacute; ph&iacute;m tắt truy cập BOOT kh&aacute;c nhau, bạn c&oacute; thể t&igrave;m kiếm tr&ecirc;n mạng bằng từ kh&oacute;a &quot;Ph&iacute;m tắt BOOT + t&ecirc;n h&atilde;ng laptop&quot;.​</p>

<p>Mẹo nhỏ: Nếu kh&ocirc;ng biết ph&iacute;m tắt k&iacute;ch hoạt Menu BOOT của laptop bạn c&oacute; thể thử lần lượt ph&iacute;m từ F2 đến F12, c&aacute;c ph&iacute;m Del hoặc Esc.</p>

<p>Ở đ&acirc;y m&aacute;y m&igrave;nh d&ugrave;ng l&agrave; Dell n&ecirc;n sẽ nhấn li&ecirc;n tục ph&iacute;m tắt F12 khi m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh vừa được bật l&ecirc;n, sau khi nhấn giao diện BOOT sẽ hiển thị ra. H&atilde;y chọn v&agrave;o ổ đĩa USB của bạn để c&agrave;i WIN 10.</p>

<p><img alt="Chọn vào tên ổ đĩa USB của bạn để bắt đầu cài WIN 10" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc.jpg" style="height:548px; width:730px" title="Chọn vào tên ổ đĩa USB của bạn để bắt đầu cài WIN 10" /></p>

<p>Giao diện BOOT l&agrave; giao diện ưu ti&ecirc;n khởi động, khi truy cập v&agrave;o đ&acirc;y bạn c&oacute; thể y&ecirc;u cầu m&aacute;y t&iacute;nh khởi động v&agrave;o USB (để c&agrave;i Win) hoặc y&ecirc;u cầu m&aacute;y t&iacute;nh truy cập v&agrave;o ổ cứng (để truy cập v&agrave;o Win).</p>

<p><strong>Bước 2:</strong>&nbsp;Chọn v&agrave;o ng&ocirc;n ngữ tại mục&nbsp;<strong>Language to install</strong>&nbsp;(khuyến nghị giữ nguy&ecirc;n&nbsp;<strong>English United States</strong>) &gt; Chọn định dạng thời gian tại mục Time and curency format &nbsp;(khuyến nghị giữ nguy&ecirc;n English United States) &gt; Chọn định dạng bạn ph&iacute;m tại mục Keyboard or input method (khuyến nghị giữ nguy&ecirc;n US) &gt; Nhấn&nbsp;<strong>Next&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn ngôn ngữ, định dạng ngày tháng, bàn phím. Nhấn Next để tiếp tục" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc.png" title="Chọn ngôn ngữ, định dạng ngày tháng, bàn phím. Nhấn Next để tiếp tục" /></p>

<p><strong>Bước 3:&nbsp;</strong>Nhập v&agrave;o đoạn&nbsp;<strong>key c&agrave;i đặt Windows</strong>&nbsp;của bạn (key n&agrave;y bạn c&oacute; thể mua tại c&aacute;c cửa h&agrave;ng b&aacute;n Windows 10 bản quyền như Điện m&aacute;y XANH chẳng hạn) &gt; Nhấn&nbsp;<strong>Next&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Nhập vào key cài đặt Windows 10" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-3.png" title="Nhập vào key cài đặt Windows 10" /></p>

<p><strong>Bước 4:&nbsp;</strong>Đồng &yacute; c&aacute;c điều khoản v&agrave; nhấn&nbsp;<strong>Next&nbsp;</strong>để chuyển sang bước kế tiếp.</p>

<p><img alt="Đồng ý các điều khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-4.png" title="Đồng ý các điều khoản" /></p>

<p><strong>Bước 5:&nbsp;</strong>Nhấn chọn&nbsp;<strong>Custom&nbsp;</strong>(nếu bạn muốn c&agrave;i đặt Windows 10 mới), hoặc chọn&nbsp;<strong>Upgrade&nbsp;</strong>để n&acirc;ng cấp từ phi&ecirc;n bản Windows cũ hơn (Windows 7, 8, 8.1, 10) l&ecirc;n phi&ecirc;n bản Windows 10 mới nhất m&agrave; vẫn giữ nguy&ecirc;n c&aacute;c tập tin, phần mềm đ&atilde; tải về trước đ&oacute;.</p>

<p>Ở đ&acirc;y m&igrave;nh muốn c&agrave;i đặt mới Windows 10 n&ecirc;n sẽ chọn v&agrave;o&nbsp;<strong>Custom</strong>.</p>

<p><img alt="Nhấn chọn vào Custom" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-5.png" title="Nhấn chọn vào Custom" /></p>

<p><strong>Bước 6:&nbsp;</strong>Chọn v&agrave;o ổ đĩa bạn c&agrave;i Windows, lưu &yacute; ổ n&agrave;y sẽ bị format (x&oacute;a to&agrave;n bộ dữ liệu) sau khi c&agrave;i đặt Windows 10. Ngo&agrave;i ra, một th&ocirc;ng tin quan trọng nữa cần ch&uacute; &yacute; l&agrave; phải chọng đ&uacute;ng ổ đĩa cần c&agrave;i, nếu chọn nhầm ổ kh&aacute;c sẽ khiến m&aacute;y t&iacute;nh của bạn mất dữ liệu.</p>

<p>Sau khi chọn ổ đĩa h&atilde;y nhấn New để tạo ph&acirc;n v&ugrave;ng mới.</p>

<p><img alt="Nhấn chọn New" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-6.png" title="Nhấn chọn New" /></p>

<p>Nhập v&agrave;o dung lượng cần tạo (1024 MB = 1 GB), nếu bạn muốn tạo ổ đĩa chứa hệ điều h&agrave;nh c&oacute; dung lượng 60 GB th&igrave; c&oacute; thể nhập v&agrave;o 1020*60=61.4040 &gt; Sau đ&oacute; nhấn Apply để lưu lại.</p>

<p><img alt="Nhập dung lượng ổ đĩa chứa hệ điều hành" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-7.png" title="Nhập dung lượng ổ đĩa chứa hệ điều hành" /></p>

<p>Đối với một số trường hợp bạn sẽ kh&ocirc;ng nhấn được chữ New, l&uacute;c n&agrave;y bạn c&oacute; thể nhấn Format để bắt đầu tiến h&agrave;nh x&oacute;a ph&acirc;n v&ugrave;ng trước khi c&agrave;i đặt Windows. Hệ thống sẽ hỏi bạn c&oacute; muốn x&oacute;a to&agrave;n bộ dữ liệu trong ph&acirc;n v&ugrave;ng trước khi Format hay kh&ocirc;ng? Nhấn chọn OK nh&eacute;!</p>

<p><img alt="Format phân vùng" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-9.png" title="Format phân vùng" /></p>

<p>L&uacute;c n&agrave;y hệ thống sẽ ph&aacute;t sinh ra nhất nhiều ph&acirc;n v&ugrave;ng, đ&acirc;y l&agrave; những ph&acirc;n v&ugrave;ng c&oacute; k&iacute;ch thước nhỏ nhưng rất quan trọng, v&igrave; thế bạn&nbsp;<strong>kh&ocirc;ng được x&oacute;a</strong>&nbsp;ch&uacute;ng nh&eacute;! Thay v&agrave;o đ&oacute; h&atilde;y chọn v&agrave;o ph&acirc;n v&ugrave;ng muốn c&agrave;i đặt Windows 10 v&agrave; chọn&nbsp;<strong>Next</strong>.</p>

<p><img alt="Nhấn Next" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-10.png" title="Nhấn Next" /></p>

<p><strong>Bước 7:</strong>&nbsp;Qu&aacute; tr&igrave;nh c&agrave;i đặt Windows 10 sẽ diễn ra ho&agrave;n to&agrave;n tự động.</p>

<p><img alt="Quá trình cài đặt Windows 10 đang diễn ra" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-11.png" title="Quá trình cài đặt Windows 10 đang diễn ra" /></p>

<p><strong>Bước 8:</strong>&nbsp;Sau khi ho&agrave;n tất, m&aacute;y t&iacute;nh sẽ khởi động lại một lần nữa v&agrave; y&ecirc;u cầu người d&ugrave;ng thiết lập một số cấu h&igrave;nh như sau:</p>

<p>Chọn ng&ocirc;n ngữ, khuy&ecirc;n chọn&nbsp;<strong>United States</strong>&nbsp;&gt; Nhấn&nbsp;<strong>Yes&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn ngôn ngữ" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-12.png" title="Chọn ngôn ngữ" /></p>

<p>Chọn b&agrave;n ph&iacute;m, khuy&ecirc;n chọn&nbsp;<strong>US&nbsp;</strong>&gt; Nhấn&nbsp;<strong>Yes&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn bàn phím, khuyên chọn US &gt; Nhấn Yes để tiếp tục." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-13.png" title="Chọn bàn phím, khuyên chọn US &gt; Nhấn Yes để tiếp tục." /></p>

<p>Nhấn&nbsp;<strong>Skip&nbsp;</strong>để bỏ qua, nếu muốn thiết lập b&agrave;n ph&iacute;m thứ 2 bạn h&atilde;y nhấn v&agrave;o Add layout, ở đ&acirc;y m&igrave;nh sẽ nhấn&nbsp;<strong>Skip</strong>.</p>

<p><img alt="Chọn ngôn ngữ, khuyên chọn United States &gt; Nhấn Yes để tiếp tục." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-14.png" title="Chọn ngôn ngữ, khuyên chọn United States &gt; Nhấn Yes để tiếp tục." /></p>

<p>Chọn thiết lập mục đ&iacute;ch sử dụng, ở đ&acirc;y m&igrave;nh chọn v&agrave;o&nbsp;<strong>Set up for personal use</strong>&nbsp;(sử dụng c&aacute; nh&acirc;n).</p>

<p><img alt="Chọn thiết lập mục đích sử dụng, ở đây mình chọn vào Set up for personal use (sử dụng cá nhân)." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-15.png" title="Chọn thiết lập mục đích sử dụng, ở đây mình chọn vào Set up for personal use (sử dụng cá nhân)." /></p>

<p>Nhập v&agrave;o t&ecirc;n t&agrave;i khoản Microsoft của bạn, nếu chưa c&oacute; h&atilde;y nhấn v&agrave;o Create account để tạo t&agrave;i khoản mới. Ở đ&acirc;y m&igrave;nh sẽ chọn v&agrave;o một mục kh&aacute;c l&agrave;&nbsp;<strong>Offline Account</strong>&nbsp;để tạo t&agrave;i khoản nội bộ (kh&ocirc;ng phải t&agrave;i khoản Microsoft) &gt; Sau đ&oacute; nhấn&nbsp;<strong>Next</strong>.</p>

<p><img alt="Đăng nhập tài khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-17.png" title="Đăng nhập tài khoản" /></p>

<p>Nhấn chọn v&agrave;o Limited experience để bỏ qua t&iacute;nh năng tải, đồng bộ c&aacute;c ứng dụng mặc định của Microsoft.</p>

<p><img alt="Đăng nhập tài khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-18.png" title="Đăng nhập tài khoản" /></p>

<p>Nhập v&agrave;o t&ecirc;n cho m&aacute;y t&iacute;nh.</p>

<p><img alt="Nhập vào mật khẩu máy tính" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-21.png" title="Nhập vào mật khẩu máy tính" /></p>

<p>Nhập v&agrave;o mật khẩu đăng nhập m&aacute;y t&iacute;nh.</p>

<p><img alt="Nhập vào mật khẩu máy tính" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-22.png" title="Nhập vào mật khẩu máy tính" /></p>

<p>Trả lời c&aacute;c c&acirc;u hỏi b&iacute; mật, c&acirc;u hỏi n&agrave;y d&ugrave;ng để kh&ocirc;i phục lại mật khẩu đăng nhập m&aacute;y t&iacute;nh n&ecirc;u như bạn lỡ qu&ecirc;n, v&igrave; thế h&atilde;y ghi nhỡ kỹ hoặc lưu lại những c&acirc;u hỏi v&agrave; c&acirc;u trả lời n&agrave;y bạn nh&eacute;!</p>

<p><img alt="Trả lời câu hỏi bí mật" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-23.png" title="Trả lời câu hỏi bí mật" /></p>

<p>Nhấn&nbsp;<strong>Yes&nbsp;</strong>để chuyển qua bước kế tiếp.</p>

<p><img alt="Nhấn Yes" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-24.png" title="Nhấn Yes" /></p>

<p>Nhấn&nbsp;<strong>Acpect</strong>.</p>

<p><img alt="Nhấn Accept" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-25.png" title="Nhấn Accept" /></p>

<p><strong>Bước 9:</strong>&nbsp;Sau khi ho&agrave;n tất, giao diện Desktop quen thuộc của Windows 10 sẽ hiển thị l&ecirc;n. Ch&uacute;c mừng bạn đ&atilde; ho&agrave;n th&agrave;nh qu&aacute; tr&igrave;nh c&agrave;i đặt v&agrave; h&atilde;y tự thưởng cho m&igrave;nh một nụ cười nh&eacute;!</p>

<p><strong>Lưu &yacute;:</strong>&nbsp;Sau khi ho&agrave;n tất c&agrave;i đặt, bạn n&ecirc;n kết nối m&aacute;y t&iacute;nh với mạng Wifi để hệ thống c&oacute; thể tải về c&aacute;c bản cập nhật Driver, phần mềm, bản v&aacute; bảo mật. Điều n&agrave;y gi&uacute;p thiết bị của bạn hoạt động trơn tru hơn, tăng hiệu năng trong qu&aacute; tr&igrave;nh sử dụng.</p>

<p>Ch&uacute;c c&aacute;c bạn thao t&aacute;c th&agrave;nh c&ocirc;ng! V&agrave; nếu trong qu&aacute; tr&igrave;nh thực hiện c&oacute; bất kỳ thắc mắc g&igrave; th&igrave; đừng ngần ngại để lại c&acirc;u hỏi ngay b&ecirc;n dưới phần b&igrave;nh luận nh&eacute;!</p>
', 0, CAST(N'2022-04-11T00:00:00' AS SmallDateTime), 1, 3)
INSERT [dbo].[TinTuc] ([matin], [tieude], [hinhnen], [tomtat], [slug], [noidung], [luotxem], [ngaycapnhat], [xuatban], [machude]) VALUES (4, N'Hướng dẫn cài đặt Win 11', N'huong-dan-cai-win-10.png', NULL, N'huong-dan-cai-dat-win-11', N'<h3><strong>Lợi &iacute;ch của việc c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<ul>
	<li>Dễ d&agrave;ng thực hiện, c&oacute; thể di chuyển c&agrave;i đặt cho nhiều thiết bị.</li>
	<li>Đ&acirc;y được xem l&agrave; một trong những c&aacute;ch c&agrave;i Win 10 đơn giản nhất hiện nay, thậm ch&iacute; người c&oacute; kiến thức hạn chế về laptop cũng c&oacute; thể l&agrave;m được.</li>
</ul>

<h3><strong>Y&ecirc;u cầu cấu h&igrave;nh tối thiểu để c&agrave;i Windows 10</strong></h3>

<ul>
	<li>Bộ vi xử l&yacute;: Tốc độ tối thiểu 1 GHz , c&oacute; hỗ trợ PAE, NX v&agrave; SSE2.</li>
	<li>Dung lượng RAM: Tối thiểu 1 GB (đối với phi&ecirc;n bản 32 bit) hoặc 2 GB (đối với phi&ecirc;n bản 64 bit).</li>
	<li>Bộ nhớ tối thiểu: 16 GB (với bản 32 bit) hoặc 20 GB (với bản 64 bit).</li>
	<li>Card đồ họa: Microsoft DirectX 9 với tr&igrave;nh điều khiển WDDM.</li>
</ul>

<h3><strong>Tổng quan quy tr&igrave;nh c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<p><img alt="USB Boot" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-2.JPG" style="height:452px; width:730px" title="USB Boot" /></p>

<p><strong>Bước 1:&nbsp;</strong>Tải file c&agrave;i đặt Windows 10 (file ISO).</p>

<p><strong>Bước 2:&nbsp;</strong>Sử dụng USB để tạo USB Boot cho file c&agrave;i đặt Windows 10 vừa tải về.</p>

<p><strong>Bước 3:&nbsp;</strong>Sử dụng USB Boot vừa tạo để c&agrave;i đặt Windows 10 tr&ecirc;n m&aacute;y t&iacute;nh, laptop.</p>

<h3><strong>Cần chuẩn bị g&igrave; trước khi c&agrave;i đặt Windows 10 bằng USB Boot</strong></h3>

<p>Cần tải về file c&agrave;i đặt Windows 10 (file ISO), cụ thể hơn bạn c&oacute; thể xem hướng dẫn sau:</p>

<ul>
	<li><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-cach-tai-windows-10-1218719" target="_blank" title="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft" type="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft">C&aacute;ch tải Windows 10, tải file ISO Windows 10 ch&iacute;nh thức từ Microsoft</a>.</li>
</ul>

<p><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-cach-tai-windows-10-1218719" target="_blank" title="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft" type="Cách tải Windows 10, tải file ISO Windows 10 chính thức từ Microsoft">​​​</a>​Chuẩn bị USB c&oacute; dung lượng lớn hơn 4 GB, sau đ&oacute; tạo USB Boot cho qu&aacute; tr&igrave;nh c&agrave;i Windows 10, chi tiết hơn bạn c&oacute; thể tham khảo hướng dẫn sau:</p>

<ul>
	<li><a href="https://www.dienmayxanh.com/kinh-nghiem-hay/huong-dan-tao-usb-boot-de-cai-win-tren-ca-2-chuan-1218657" target="_blank" title="Hướng dẫn tạo USB Boot cài WIN 7, 10 trên cả 2 chuẩn UEFI và LEGACY" type="Hướng dẫn tạo USB Boot cài WIN 7, 10 trên cả 2 chuẩn UEFI và LEGACY">Hướng dẫn tạo USB Boot c&agrave;i WIN 7, 10 tr&ecirc;n cả 2 chuẩn UEFI v&agrave; LEGACY.</a></li>
</ul>

<h3><strong>Hướng dẫn c&aacute;ch c&agrave;i đặt Windows 10 đơn giản nhất bằng USB Boot</strong></h3>

<p>Thời gian c&agrave;i đặt Windows 10 nhanh hay chậm t&ugrave;y thuộc v&agrave;o tốc độ đọc ghi USB v&agrave; cấu h&igrave;nh m&aacute;y t&iacute;nh người d&ugrave;ng. Th&ocirc;ng thường qu&aacute; tr&igrave;nh n&agrave;y mất tầm&nbsp;<strong>20-60 ph&uacute;t</strong>.</p>

<p><strong>Bước 1:</strong>&nbsp;Kết nối USB Boot vừa chuẩn bị ở tr&ecirc;n v&agrave;o m&aacute;y t&iacute;nh, laptop cần c&agrave;i Win 10.</p>

<p><strong>Bước 2:&nbsp;</strong>Nhấn n&uacute;t&nbsp;<strong>nguồn&nbsp;</strong>để khởi động m&aacute;y, khi&nbsp;<a href="https://www.dienmayxanh.com/man-hinh-may-tinh" target="_blank" title="màn hình máy tính">m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh</a>&nbsp;vừa bật bạn h&atilde;y&nbsp;<strong>nhấn li&ecirc;n tục ph&iacute;m tắt</strong>&nbsp;để truy cập v&agrave;o&nbsp;<strong>menu BOOT</strong>. Mỗi d&ograve;ng laptop kh&aacute;c nhau sẽ c&oacute; ph&iacute;m tắt truy cập BOOT kh&aacute;c nhau, bạn c&oacute; thể t&igrave;m kiếm tr&ecirc;n mạng bằng từ kh&oacute;a &quot;Ph&iacute;m tắt BOOT + t&ecirc;n h&atilde;ng laptop&quot;.​</p>

<p>Mẹo nhỏ: Nếu kh&ocirc;ng biết ph&iacute;m tắt k&iacute;ch hoạt Menu BOOT của laptop bạn c&oacute; thể thử lần lượt ph&iacute;m từ F2 đến F12, c&aacute;c ph&iacute;m Del hoặc Esc.</p>

<p>Ở đ&acirc;y m&aacute;y m&igrave;nh d&ugrave;ng l&agrave; Dell n&ecirc;n sẽ nhấn li&ecirc;n tục ph&iacute;m tắt F12 khi m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh vừa được bật l&ecirc;n, sau khi nhấn giao diện BOOT sẽ hiển thị ra. H&atilde;y chọn v&agrave;o ổ đĩa USB của bạn để c&agrave;i WIN 10.</p>

<p><img alt="Chọn vào tên ổ đĩa USB của bạn để bắt đầu cài WIN 10" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc.jpg" style="height:548px; width:730px" title="Chọn vào tên ổ đĩa USB của bạn để bắt đầu cài WIN 10" /></p>

<p>Giao diện BOOT l&agrave; giao diện ưu ti&ecirc;n khởi động, khi truy cập v&agrave;o đ&acirc;y bạn c&oacute; thể y&ecirc;u cầu m&aacute;y t&iacute;nh khởi động v&agrave;o USB (để c&agrave;i Win) hoặc y&ecirc;u cầu m&aacute;y t&iacute;nh truy cập v&agrave;o ổ cứng (để truy cập v&agrave;o Win).</p>

<p><strong>Bước 2:</strong>&nbsp;Chọn v&agrave;o ng&ocirc;n ngữ tại mục&nbsp;<strong>Language to install</strong>&nbsp;(khuyến nghị giữ nguy&ecirc;n&nbsp;<strong>English United States</strong>) &gt; Chọn định dạng thời gian tại mục Time and curency format &nbsp;(khuyến nghị giữ nguy&ecirc;n English United States) &gt; Chọn định dạng bạn ph&iacute;m tại mục Keyboard or input method (khuyến nghị giữ nguy&ecirc;n US) &gt; Nhấn&nbsp;<strong>Next&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn ngôn ngữ, định dạng ngày tháng, bàn phím. Nhấn Next để tiếp tục" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc.png" title="Chọn ngôn ngữ, định dạng ngày tháng, bàn phím. Nhấn Next để tiếp tục" /></p>

<p><strong>Bước 3:&nbsp;</strong>Nhập v&agrave;o đoạn&nbsp;<strong>key c&agrave;i đặt Windows</strong>&nbsp;của bạn (key n&agrave;y bạn c&oacute; thể mua tại c&aacute;c cửa h&agrave;ng b&aacute;n Windows 10 bản quyền như Điện m&aacute;y XANH chẳng hạn) &gt; Nhấn&nbsp;<strong>Next&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Nhập vào key cài đặt Windows 10" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-3.png" title="Nhập vào key cài đặt Windows 10" /></p>

<p><strong>Bước 4:&nbsp;</strong>Đồng &yacute; c&aacute;c điều khoản v&agrave; nhấn&nbsp;<strong>Next&nbsp;</strong>để chuyển sang bước kế tiếp.</p>

<p><img alt="Đồng ý các điều khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-4.png" title="Đồng ý các điều khoản" /></p>

<p><strong>Bước 5:&nbsp;</strong>Nhấn chọn&nbsp;<strong>Custom&nbsp;</strong>(nếu bạn muốn c&agrave;i đặt Windows 10 mới), hoặc chọn&nbsp;<strong>Upgrade&nbsp;</strong>để n&acirc;ng cấp từ phi&ecirc;n bản Windows cũ hơn (Windows 7, 8, 8.1, 10) l&ecirc;n phi&ecirc;n bản Windows 10 mới nhất m&agrave; vẫn giữ nguy&ecirc;n c&aacute;c tập tin, phần mềm đ&atilde; tải về trước đ&oacute;.</p>

<p>Ở đ&acirc;y m&igrave;nh muốn c&agrave;i đặt mới Windows 10 n&ecirc;n sẽ chọn v&agrave;o&nbsp;<strong>Custom</strong>.</p>

<p><img alt="Nhấn chọn vào Custom" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-5.png" title="Nhấn chọn vào Custom" /></p>

<p><strong>Bước 6:&nbsp;</strong>Chọn v&agrave;o ổ đĩa bạn c&agrave;i Windows, lưu &yacute; ổ n&agrave;y sẽ bị format (x&oacute;a to&agrave;n bộ dữ liệu) sau khi c&agrave;i đặt Windows 10. Ngo&agrave;i ra, một th&ocirc;ng tin quan trọng nữa cần ch&uacute; &yacute; l&agrave; phải chọng đ&uacute;ng ổ đĩa cần c&agrave;i, nếu chọn nhầm ổ kh&aacute;c sẽ khiến m&aacute;y t&iacute;nh của bạn mất dữ liệu.</p>

<p>Sau khi chọn ổ đĩa h&atilde;y nhấn New để tạo ph&acirc;n v&ugrave;ng mới.</p>

<p><img alt="Nhấn chọn New" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-6.png" title="Nhấn chọn New" /></p>

<p>Nhập v&agrave;o dung lượng cần tạo (1024 MB = 1 GB), nếu bạn muốn tạo ổ đĩa chứa hệ điều h&agrave;nh c&oacute; dung lượng 60 GB th&igrave; c&oacute; thể nhập v&agrave;o 1020*60=61.4040 &gt; Sau đ&oacute; nhấn Apply để lưu lại.</p>

<p><img alt="Nhập dung lượng ổ đĩa chứa hệ điều hành" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-7.png" title="Nhập dung lượng ổ đĩa chứa hệ điều hành" /></p>

<p>Đối với một số trường hợp bạn sẽ kh&ocirc;ng nhấn được chữ New, l&uacute;c n&agrave;y bạn c&oacute; thể nhấn Format để bắt đầu tiến h&agrave;nh x&oacute;a ph&acirc;n v&ugrave;ng trước khi c&agrave;i đặt Windows. Hệ thống sẽ hỏi bạn c&oacute; muốn x&oacute;a to&agrave;n bộ dữ liệu trong ph&acirc;n v&ugrave;ng trước khi Format hay kh&ocirc;ng? Nhấn chọn OK nh&eacute;!</p>

<p><img alt="Format phân vùng" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-9.png" title="Format phân vùng" /></p>

<p>L&uacute;c n&agrave;y hệ thống sẽ ph&aacute;t sinh ra nhất nhiều ph&acirc;n v&ugrave;ng, đ&acirc;y l&agrave; những ph&acirc;n v&ugrave;ng c&oacute; k&iacute;ch thước nhỏ nhưng rất quan trọng, v&igrave; thế bạn&nbsp;<strong>kh&ocirc;ng được x&oacute;a</strong>&nbsp;ch&uacute;ng nh&eacute;! Thay v&agrave;o đ&oacute; h&atilde;y chọn v&agrave;o ph&acirc;n v&ugrave;ng muốn c&agrave;i đặt Windows 10 v&agrave; chọn&nbsp;<strong>Next</strong>.</p>

<p><img alt="Nhấn Next" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-10.png" title="Nhấn Next" /></p>

<p><strong>Bước 7:</strong>&nbsp;Qu&aacute; tr&igrave;nh c&agrave;i đặt Windows 10 sẽ diễn ra ho&agrave;n to&agrave;n tự động.</p>

<p><img alt="Quá trình cài đặt Windows 10 đang diễn ra" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-11.png" title="Quá trình cài đặt Windows 10 đang diễn ra" /></p>

<p><strong>Bước 8:</strong>&nbsp;Sau khi ho&agrave;n tất, m&aacute;y t&iacute;nh sẽ khởi động lại một lần nữa v&agrave; y&ecirc;u cầu người d&ugrave;ng thiết lập một số cấu h&igrave;nh như sau:</p>

<p>Chọn ng&ocirc;n ngữ, khuy&ecirc;n chọn&nbsp;<strong>United States</strong>&nbsp;&gt; Nhấn&nbsp;<strong>Yes&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn ngôn ngữ" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-12.png" title="Chọn ngôn ngữ" /></p>

<p>Chọn b&agrave;n ph&iacute;m, khuy&ecirc;n chọn&nbsp;<strong>US&nbsp;</strong>&gt; Nhấn&nbsp;<strong>Yes&nbsp;</strong>để tiếp tục.</p>

<p><img alt="Chọn bàn phím, khuyên chọn US &gt; Nhấn Yes để tiếp tục." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-13.png" title="Chọn bàn phím, khuyên chọn US &gt; Nhấn Yes để tiếp tục." /></p>

<p>Nhấn&nbsp;<strong>Skip&nbsp;</strong>để bỏ qua, nếu muốn thiết lập b&agrave;n ph&iacute;m thứ 2 bạn h&atilde;y nhấn v&agrave;o Add layout, ở đ&acirc;y m&igrave;nh sẽ nhấn&nbsp;<strong>Skip</strong>.</p>

<p><img alt="Chọn ngôn ngữ, khuyên chọn United States &gt; Nhấn Yes để tiếp tục." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-14.png" title="Chọn ngôn ngữ, khuyên chọn United States &gt; Nhấn Yes để tiếp tục." /></p>

<p>Chọn thiết lập mục đ&iacute;ch sử dụng, ở đ&acirc;y m&igrave;nh chọn v&agrave;o&nbsp;<strong>Set up for personal use</strong>&nbsp;(sử dụng c&aacute; nh&acirc;n).</p>

<p><img alt="Chọn thiết lập mục đích sử dụng, ở đây mình chọn vào Set up for personal use (sử dụng cá nhân)." src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-15.png" title="Chọn thiết lập mục đích sử dụng, ở đây mình chọn vào Set up for personal use (sử dụng cá nhân)." /></p>

<p>Nhập v&agrave;o t&ecirc;n t&agrave;i khoản Microsoft của bạn, nếu chưa c&oacute; h&atilde;y nhấn v&agrave;o Create account để tạo t&agrave;i khoản mới. Ở đ&acirc;y m&igrave;nh sẽ chọn v&agrave;o một mục kh&aacute;c l&agrave;&nbsp;<strong>Offline Account</strong>&nbsp;để tạo t&agrave;i khoản nội bộ (kh&ocirc;ng phải t&agrave;i khoản Microsoft) &gt; Sau đ&oacute; nhấn&nbsp;<strong>Next</strong>.</p>

<p><img alt="Đăng nhập tài khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-17.png" title="Đăng nhập tài khoản" /></p>

<p>Nhấn chọn v&agrave;o Limited experience để bỏ qua t&iacute;nh năng tải, đồng bộ c&aacute;c ứng dụng mặc định của Microsoft.</p>

<p><img alt="Đăng nhập tài khoản" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-18.png" title="Đăng nhập tài khoản" /></p>

<p>Nhập v&agrave;o t&ecirc;n cho m&aacute;y t&iacute;nh.</p>

<p><img alt="Nhập vào mật khẩu máy tính" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-21.png" title="Nhập vào mật khẩu máy tính" /></p>

<p>Nhập v&agrave;o mật khẩu đăng nhập m&aacute;y t&iacute;nh.</p>

<p><img alt="Nhập vào mật khẩu máy tính" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-22.png" title="Nhập vào mật khẩu máy tính" /></p>

<p>Trả lời c&aacute;c c&acirc;u hỏi b&iacute; mật, c&acirc;u hỏi n&agrave;y d&ugrave;ng để kh&ocirc;i phục lại mật khẩu đăng nhập m&aacute;y t&iacute;nh n&ecirc;u như bạn lỡ qu&ecirc;n, v&igrave; thế h&atilde;y ghi nhỡ kỹ hoặc lưu lại những c&acirc;u hỏi v&agrave; c&acirc;u trả lời n&agrave;y bạn nh&eacute;!</p>

<p><img alt="Trả lời câu hỏi bí mật" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-23.png" title="Trả lời câu hỏi bí mật" /></p>

<p>Nhấn&nbsp;<strong>Yes&nbsp;</strong>để chuyển qua bước kế tiếp.</p>

<p><img alt="Nhấn Yes" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-24.png" title="Nhấn Yes" /></p>

<p>Nhấn&nbsp;<strong>Acpect</strong>.</p>

<p><img alt="Nhấn Accept" src="https://cdn.tgdd.vn/Files/2019/11/14/1218882/huong-dan-cai-dat-windows-7-10-don-gian-nhat-ai-cung-lam-duoc-25.png" title="Nhấn Accept" /></p>

<p><strong>Bước 9:</strong>&nbsp;Sau khi ho&agrave;n tất, giao diện Desktop quen thuộc của Windows 10 sẽ hiển thị l&ecirc;n. Ch&uacute;c mừng bạn đ&atilde; ho&agrave;n th&agrave;nh qu&aacute; tr&igrave;nh c&agrave;i đặt v&agrave; h&atilde;y tự thưởng cho m&igrave;nh một nụ cười nh&eacute;!</p>

<p><strong>Lưu &yacute;:</strong>&nbsp;Sau khi ho&agrave;n tất c&agrave;i đặt, bạn n&ecirc;n kết nối m&aacute;y t&iacute;nh với mạng Wifi để hệ thống c&oacute; thể tải về c&aacute;c bản cập nhật Driver, phần mềm, bản v&aacute; bảo mật. Điều n&agrave;y gi&uacute;p thiết bị của bạn hoạt động trơn tru hơn, tăng hiệu năng trong qu&aacute; tr&igrave;nh sử dụng.</p>

<p>Ch&uacute;c c&aacute;c bạn thao t&aacute;c th&agrave;nh c&ocirc;ng! V&agrave; nếu trong qu&aacute; tr&igrave;nh thực hiện c&oacute; bất kỳ thắc mắc g&igrave; th&igrave; đừng ngần ngại để lại c&acirc;u hỏi ngay b&ecirc;n dưới phần b&igrave;nh luận nh&eacute;!</p>
', 0, CAST(N'2022-04-29T00:00:00' AS SmallDateTime), 1, 3)
INSERT [dbo].[TinTuc] ([matin], [tieude], [hinhnen], [tomtat], [slug], [noidung], [luotxem], [ngaycapnhat], [xuatban], [machude]) VALUES (5, N'Code Liên Quân mới 6/2022', N'Code-Lien-Quan-640.jpg', N'Test nhân phẩm', N'code-lien-quan-640', N'<h2>Code Li&ecirc;n Qu&acirc;n mới nhất th&aacute;ng 6/2022</h2>

<p>Dưới đ&acirc;y l&agrave; to&agrave;n bộ giftcode của Li&ecirc;n Qu&acirc;n Mobile m&agrave; Quantrimang đ&atilde; thu thập v&agrave; tổng hợp lại được. Người chơi n&ecirc;n tranh thủ nhập sớm những giftcode n&agrave;y để nhận những phần qu&agrave; ingame gi&aacute; trị.</p>

<table border="1">
	<tbody>
		<tr>
			<td><strong>Giftcode</strong></td>
			<td><strong>Vật phẩm</strong></td>
			<td><strong>Thời hạn</strong></td>
		</tr>
		<tr>
			<td>
			<pre>
<code>COCXAOV125_BOGHYHF7</code></pre>
			</td>
			<td>
			<p>Thẻ nh&acirc;n đ&ocirc;i v&agrave;ng 4 trận thắng</p>
